        var = d["gastos_var"]["Monto"].sum() if not d["gastos_var"].empty else 0.0
        seg = d["seguimiento"]["Monto"].sum() if not d["seguimiento"].empty else 0.0
        aho = d["ahorros"]["Monto"].sum() if not d["ahorros"].empty else 0.0
        gas = fac + var + seg
