def send_security_alert(target_email, event_type, details):
    log_entry = {
        "timestamp": datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
        "target_email": target_email,
        "event_type": event_type,
        "details": details,
        "correo_enviado": "No configurado"
    }
    
    cfg = st.session_state.smtp_config
    if cfg["active"] and cfg["sender"] and cfg["password"] and cfg["recipient"]:
        try:
            msg = MIMEMultipart("alternative")
            msg["Subject"] = f"🚨 [ALERTA SEGURIDAD] {event_type} - OptiBudget Pro"
            msg["From"] = cfg["sender"]
            msg["To"] = cfg["recipient"]
            
            html = f"""
            <div style="font-family: Arial, sans-serif; padding: 20px; border: 1px solid #E2E8F0; border-radius: 8px;">
              <h2 style="color: #D74546; margin-top: 0;">🚨 Alerta de Violación / Incidente de Seguridad</h2>
              <p>El sistema de seguridad de <b>OptiBudget Pro</b> ha detectado un evento anómalo:</p>
              <table style="width: 100%; border-collapse: collapse; margin: 15px 0;">
                <tr style="background: #F8FAFC;"><td style="padding: 8px; font-weight: bold;">Evento:</td><td style="padding: 8px; color: #D74546;">{event_type}</td></tr>
                <tr><td style="padding: 8px; font-weight: bold;">Fecha y Hora:</td><td style="padding: 8px;">{log_entry['timestamp']}</td></tr>
                <tr style="background: #F8FAFC;"><td style="padding: 8px; font-weight: bold;">Cuenta Objetivo:</td><td style="padding: 8px;">{target_email}</td></tr>
                <tr><td style="padding: 8px; font-weight: bold;">Detalles:</td><td style="padding: 8px;">{details}</td></tr>
              </table>
              <hr style="border: 0; border-top: 1px solid #E2E8F0;">
              <p style="font-size: 0.85rem; color: #64748B;">Notificación generada automáticamente por OptiBudget Pro Security Core.</p>
            </div>
            """
            msg.attach(MIMEText(html, "html"))
            
            server = smtplib.SMTP(cfg["server"], cfg["port"], timeout=6)
            server.starttls()
            server.login(cfg["sender"], cfg["password"])
            server.sendmail(cfg["sender"], cfg["recipient"], msg.as_string())
            server.quit()
            log_entry["correo_enviado"] = f"Enviado a {cfg['recipient']}"
        except Exception as e:
            log_entry["correo_enviado"] = f"Error de envío: {str(e)}"
            
    st.session_state.audit_log.append(log_entry)

